void INIWriter::write(const std::string& filepath, const INIReader& reader, const bool overwrite) {
    if (!overwrite && std::ifstream{filepath}) {
        throw std::runtime_error("File already exists: " + filepath);
    }

    std::ofstream out(filepath);
    if (!out.is_open()) {
        throw std::runtime_error("Failed to open file for writing: " + filepath);
    }

    const auto& sections = reader.Sections();
    for (const auto& section : sections) {
        out << '[' << section << ']' << '
';
        const auto& keys = reader.Keys(section);
        for (const auto& key : keys) {
            std::string value = reader.Get(section, key);
            out << key << '=' << value << '
';
        }
    }
}
